17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.samples.petclinic.util.Households;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
111	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
112	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
113	        }
114	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
115	        rejectDuplicateTelephone(telephone);
116	        owner.setTelephone(telephone);
117	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(java.time.LocalDate.now());
120	        }
121	        owner.setCustomerCode(assignCustomerCode(owner.getLastName()));
122	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    /**
131	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
132	     * LAST3 is the upper-cased first three letters of the last name and NNNN is a global 4-digit
133	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
134	     *
135	     * @param lastName the owner's last name
136	     * @return the assigned customer code
137	     */
138	    private String assignCustomerCode(String lastName) {
139	        String name = lastName == null ? "" : lastName;
140	        String last3 = name.substring(0, Math.min(3, name.length()))
141	            .toUpperCase(java.util.Locale.ROOT);
142	        int sequence = this.clinicService.findAllOwners().size() + 1;
143	        return String.format("%s-%04d", last3, sequence);
144	    }
145	
146	    /**
147	     * Counts how many existing owners share the given first and last name, compared
148	     * case-insensitively, at the time this owner is created. The value excludes the owner
149	     * being created (which has not yet been saved) and is stored on the new owner and returned
150	     * as its {@code namesakeCount}.
151	     *
152	     * @param firstName the first name of the owner being created
153	     * @param lastName the last name of the owner being created
154	     * @return the number of existing owners with the same first and last name
155	     */
156	    private int countNamesakes(String firstName, String lastName) {
157	        String first = firstName == null ? "" : firstName;
158	        String last = lastName == null ? "" : lastName;
159	        return (int) this.clinicService.findAllOwners().stream()
160	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
161	                && last.equalsIgnoreCase(existing.getLastName()))
162	            .count();
163	    }
164	
165	    /**
166	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
167	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
168	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
169	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
170	     * {@code "+61412345678"}. The E.164 value is stored and returned.
171	     *
172	     * @param telephone the raw telephone as submitted
173	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
174	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
175	     */
176	    private String normalizeTelephone(String telephone) {
177	        String raw = telephone == null ? "" : telephone.trim();
178	        boolean hasCountryCode = raw.startsWith("+");
179	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
180	        if (hasCountryCode) {
181	            cleaned = cleaned.substring(1);
182	        }
183	        String digits;
184	        if (hasCountryCode) {
185	            digits = cleaned;
186	        } else {
187	            if (cleaned.startsWith("0")) {
188	                cleaned = cleaned.substring(1);
189	            }
190	            digits = "61" + cleaned;
191	        }
192	        if (!digits.matches("[0-9]{8,15}")) {
193	            throw new InvalidTelephoneException(telephone);
194	        }
195	        return "+" + digits;
196	    }
197	
198	    /**
199	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
200	     * multi-character top-level label. Deliberately lenient about the exact character set while still
201	     * rejecting values that are clearly not addresses (e.g. missing '@').
202	     */
203	    private static final java.util.regex.Pattern EMAIL_PATTERN =
204	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
205	
206	    /**
207	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
208	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
209	     * lower-cased before being stored and returned.
210	     *
211	     * @param email the raw email as submitted, may be {@code null}
212	     * @return the lower-cased email, or {@code null} when none was supplied
213	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
214	     */
215	    private String normalizeEmail(String email) {
216	        if (email == null || email.isBlank()) {
217	            return null;
218	        }
219	        String trimmed = email.trim();
220	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
221	            throw new InvalidEmailException(email);
222	        }
223	        return trimmed.toLowerCase(java.util.Locale.ROOT);
224	    }
225	
226	    /**
227	     * Common street-type abbreviations expanded to their full word during address normalization.
228	     */
229	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
230	        "ST", "STREET",
231	        "RD", "ROAD",
232	        "AVE", "AVENUE");
233	
234	    /**
235	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
236	     * whitespace collapse to a single space, the value is upper-cased and common street-type
237	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
238	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
239	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
240	     * for every address comparison (household duplicate detection and the shared household id).
241	     *
242	     * @param address the raw address as submitted
243	     * @return the normalized address
244	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
245	     */
246	    private String normalizeAddress(String address) {
247	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
248	        if (collapsed.isEmpty()) {
249	            throw new InvalidAddressException(address);
250	        }
251	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
252	        StringBuilder normalized = new StringBuilder(collapsed.length());
253	        for (int i = 0; i < tokens.length; i++) {
254	            if (i > 0) {
255	                normalized.append(' ');
256	            }
257	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
258	        }
259	        return normalized.toString();
260	    }
261	
262	    /**
263	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
264	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
265	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
266	     * {@code "+61 412 345 678"}) are still treated as duplicates.
267	     *
268	     * @param telephone the E.164 telephone of the owner being created
269	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
270	     */
271	    private void rejectDuplicateTelephone(String telephone) {
272	        boolean duplicate = this.clinicService.findAllOwners().stream()
273	            .map(Owner::getTelephone)
274	            .filter(existing -> existing != null)
275	            .map(this::toE164OrNull)
276	            .filter(existing -> existing != null)
277	            .anyMatch(telephone::equals);
278	        if (duplicate) {
279	            throw new DuplicateTelephoneException(telephone);
280	        }
281	    }
282	
283	    /**
284	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
285	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
286	     */
287	    private String toE164OrNull(String telephone) {
288	        try {
289	            return normalizeTelephone(telephone);
290	        } catch (InvalidTelephoneException e) {
291	            return null;
292	        }
293	    }
294	
295	    /**
296	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
297	     * already has the same last name and the same address. Last names are compared case-insensitively
298	     * with whitespace collapsed; addresses are compared in their normalized form (see
299	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
300	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
301	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
302	     *
303	     * @param lastName the last name of the owner being created
304	     * @param address the normalized address of the owner being created
305	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
306	     */
307	    private void rejectDuplicateHousehold(String lastName, String address) {
308	        String normalizedLastName = Households.normalize(lastName);
309	        String normalizedAddress = Households.normalize(address);
310	        boolean duplicate = this.clinicService.findAllOwners().stream()
311	            .anyMatch(existing ->
312	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
313	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
314	        if (duplicate) {
315	            throw new DuplicateHouseholdException(lastName, address);
316	        }
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
322	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
323	        if (currentOwner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        currentOwner.setAddress(ownerFieldsDto.getAddress());
327	        currentOwner.setCity(ownerFieldsDto.getCity());
328	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
329	        currentOwner.setLastName(ownerFieldsDto.getLastName());
330	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
331	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
332	        this.clinicService.saveOwner(currentOwner);
333	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Transactional
338	    @Override
339	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
340	        Owner owner = this.clinicService.findOwnerById(ownerId);
341	        if (owner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        this.clinicService.deleteOwner(owner);
345	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
346	    }
347	
348	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
349	    @Override
350	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
351	        Owner owner = this.clinicService.findOwnerById(ownerId);
352	        if (owner == null) {
353	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
354	        }
355	        HttpHeaders headers = new HttpHeaders();
356	        Pet pet = petMapper.toPet(petFieldsDto);
357	        owner.setId(ownerId);
358	        pet.setOwner(owner);
359	        pet.getType().setName(null);
360	        this.clinicService.savePet(pet);
361	        PetDto petDto = petMapper.toPetDto(pet);
362	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
363	            .buildAndExpand(pet.getId()).toUri());
364	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
370	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
371	        if (currentOwner != null) {
372	            Pet currentPet = this.clinicService.findPetById(petId);
373	            if (currentPet != null) {
374	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
375	                currentPet.setName(petFieldsDto.getName());
376	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
377	                this.clinicService.savePet(currentPet);
378	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
379	            }
